import dotenv from "dotenv";
dotenv.config();

import express from "express";
import cors from "cors";
import path from "path";
import { createServer as createViteServer } from "vite";
import fs from "fs/promises";

// Central path resolution
import { ROOT_DIR, DATA_DIR, DIST_DIR, TOOL_IMAGES_DIR } from "./src/server/paths.js";

// Server components
import { setupWhatsAppRoutes } from "./src/server/whatsapp.js";
import { setupMemoryRoutes } from "./src/server/memory.js";
import { setupToolsRoutes } from "./src/server/tools.js";
import { setupSettingsRoutes } from "./src/server/settings.js";
import { setupCampaignRoutes, startCampaignEngine } from "./src/server/campaign.js";
import { setupAuthRoutes, getUsers } from "./src/server/auth.js";
import { setupDeepgramRoutes, startDeepgramBalanceMonitor } from "./src/server/deepgram.js";
import { setupListRoutes, getLists } from "./src/server/lists.js";
import { setupUsageRoutes } from "./src/server/usage.js";
import { setupDeploymentRoutes } from "./src/server/deployment.js";
import { startAgent } from "./src/server/agent.js";

async function initializeDataDirs() {
  try {
    await fs.mkdir(DATA_DIR, { recursive: true });
    await fs.mkdir(TOOL_IMAGES_DIR, { recursive: true });
    
    // Initialize users & default lists
    await getUsers();
    await getLists();

    // Create initial JSON files if they don't exist
    const files = ["customers.json", "tools.json", "settings.json"];
    for (const file of files) {
      const filePath = path.join(DATA_DIR, file);
      try {
        await fs.access(filePath);
      } catch {
        const defaultContent = file === "settings.json" ? 
          JSON.stringify({ aiAgentEnabled: true, preferredApi: "gemini", defaultLLM: "Gemini", language: "Roman Urdu", autoReply: true, allowImageReplies: true }, null, 2) : 
          JSON.stringify(file === "tools.json" ? [] : {}, null, 2);
        await fs.writeFile(filePath, defaultContent);
      }
    }
  } catch (error) {
    console.error("Error initializing data directory:", error);
  }
}

async function startServer() {
  await initializeDataDirs();

  const app = express();
  const rawPort = process.env.PORT;
  const portOrSocket = rawPort ? (isNaN(Number(rawPort)) ? rawPort : parseInt(rawPort, 10)) : 3001;

  app.use(cors());
  app.use(express.json({ limit: '50mb' }));

  // Static serving for tool images
  app.use('/tool-images', express.static(TOOL_IMAGES_DIR));

  // Setup API Routes
  setupAuthRoutes(app);
  setupWhatsAppRoutes(app);
  setupMemoryRoutes(app);
  setupToolsRoutes(app);
  setupSettingsRoutes(app);
  setupCampaignRoutes(app);
  setupDeepgramRoutes(app);
  setupListRoutes(app);
  setupUsageRoutes(app);
  setupDeploymentRoutes(app);
  
  // Start background agent loop & campaign engine & deepgram monitor
  startAgent();
  startCampaignEngine();
  startDeepgramBalanceMonitor();

  // Mode check: explicit development mode vs production mode
  const isDev = process.env.NODE_ENV === "development";

  if (isDev) {
    console.log('[Development] Starting Vite dev server middleware...');
    const vite = await createViteServer({
      server: {
        middlewareMode: true,
        watch: {
          ignored: ['**/data/**', '**/auth/**', '**/.git/**'],
        },
      },
      appType: "spa",
    });
    app.use(vite.middlewares);
    app.use(async (req, res, next) => {
      if (req.method !== 'GET') return next();
      const url = req.originalUrl;
      try {
        let template = await fs.readFile(path.resolve(ROOT_DIR, 'index.html'), 'utf-8');
        template = await vite.transformIndexHtml(url, template);
        res.status(200).set({ 'Content-Type': 'text/html' }).end(template);
      } catch (e) {
        vite.ssrFixStacktrace(e as Error);
        next(e);
      }
    });
  } else {
    console.log('[Production] Serving frontend assets from:', DIST_DIR);

    // Serve compiled static assets
    app.use(express.static(DIST_DIR, {
      index: false,
      maxAge: '1d',
      setHeaders: (res, filePath) => {
        if (filePath.endsWith('.js') || filePath.endsWith('.mjs')) {
          res.setHeader('Content-Type', 'application/javascript; charset=UTF-8');
        } else if (filePath.endsWith('.css')) {
          res.setHeader('Content-Type', 'text/css; charset=UTF-8');
        } else if (filePath.endsWith('.json')) {
          res.setHeader('Content-Type', 'application/json; charset=UTF-8');
        }
      }
    }));

    // Prevent unhandled API routes from falling through to HTML index.html
    app.use('/api', (req, res) => {
      res.status(404).json({ error: `API route not found: ${req.method} ${req.originalUrl}` });
    });

    // Prevent missing asset requests from falling through to HTML index.html
    app.use('/assets', (req, res) => {
      res.status(404).send('Asset not found');
    });

    // SPA Wildcard Route Fallback
    app.get('*', (req, res) => {
      const indexPath = path.join(DIST_DIR, 'index.html');
      res.sendFile(indexPath, (err) => {
        if (err) {
          console.error('[Production Error] Failed to send index.html:', err);
          if (!res.headersSent) {
            res.status(500).send('Internal Server Error: SPA index.html missing');
          }
        }
      });
    });
  }

  app.listen(portOrSocket, () => {
    console.log(`Server running on ${typeof portOrSocket === 'number' ? `http://localhost:${portOrSocket}` : portOrSocket}`);
  });
}

startServer().catch(console.error);
