import { makeWASocket, useMultiFileAuthState, DisconnectReason, Browsers, downloadMediaMessage } from "@whiskeysockets/baileys";
import { Boom } from "@hapi/boom";
import { Express } from "express";
import { queueMessage } from "./agent.js";
import { transcribeAudio } from "./deepgram.js";
import pino from "pino";
import qrcode from "qrcode";
import fs from "fs/promises";
import path from "path";
import { AUTH_DIR, ROOT_DIR, DATA_DIR } from "./paths.js";

let sock: ReturnType<typeof makeWASocket> | null = null;
let qrCodeDataUrl: string | null = null;
let pairingCodeData: string | null = null;
let connectionStatus: "connecting" | "connected" | "disconnected" = "disconnected";
let isIntentionallyDisconnected = false;
let isConnecting = false;
let reconnectTimer: NodeJS.Timeout | null = null;

function getAuthDir(): string {
  return AUTH_DIR;
}

async function ensureAuthDir(): Promise<string> {
  const authDir = getAuthDir();
  await fs.mkdir(authDir, { recursive: true });

  // Migrate older auth folder if present
  const oldAuthDir = path.join(ROOT_DIR, "auth");
  try {
    const oldCreds = path.join(oldAuthDir, "creds.json");
    await fs.access(oldCreds);
    const newCreds = path.join(authDir, "creds.json");
    try {
      await fs.access(newCreds);
    } catch {
      // copy old files to data/auth
      const files = await fs.readdir(oldAuthDir);
      for (const file of files) {
        await fs.copyFile(path.join(oldAuthDir, file), path.join(authDir, file));
      }
      console.log("[WhatsApp] Migrated legacy auth files to data/auth");
    }
  } catch {
    // No legacy folder to migrate
  }

  return authDir;
}

export async function connectToWhatsApp(usePairingCode = false) {
  if (reconnectTimer) {
    clearTimeout(reconnectTimer);
    reconnectTimer = null;
  }

  if (isConnecting || (connectionStatus === "connected" && sock)) {
    return;
  }
  isConnecting = true;

  try {
    isIntentionallyDisconnected = false;
    const authDir = await ensureAuthDir();
    
    const { state, saveCreds } = await useMultiFileAuthState(authDir);
    
    connectionStatus = "connecting";
    qrCodeDataUrl = null;
    pairingCodeData = null;

    // Clean up previous socket if existing
    if (sock) {
      try {
        sock.ev.removeAllListeners("connection.update");
        sock.ev.removeAllListeners("creds.update");
        sock.ev.removeAllListeners("messages.upsert");
        sock.end(undefined);
      } catch {
        // ignore cleanup error
      }
      sock = null;
    }

    const newSock = makeWASocket({
      auth: state,
      printQRInTerminal: !usePairingCode,
      browser: usePairingCode ? ["Ubuntu", "Chrome", "20.0.04"] : Browsers.macOS("Desktop"),
      syncFullHistory: false,
      markOnlineOnConnect: true,
      logger: pino({ level: "silent" }) as any,
    });
    sock = newSock;

    newSock.ev.on("connection.update", async (update) => {
      const { connection, lastDisconnect, qr } = update;
      
      if (qr && !usePairingCode) {
        qrCodeDataUrl = await qrcode.toDataURL(qr);
      }

      if (connection === "close") {
        const statusCode = (lastDisconnect?.error as Boom)?.output?.statusCode;
        const isLoggedOut = statusCode === DisconnectReason.loggedOut;
        const isReplaced = statusCode === DisconnectReason.connectionReplaced || statusCode === 440;
        const shouldReconnect = !isLoggedOut && !isReplaced && !isIntentionallyDisconnected;
        
        connectionStatus = "disconnected";
        console.log(`[WhatsApp] Connection closed. Reason: ${statusCode || lastDisconnect?.error}. Should reconnect: ${shouldReconnect}`);
        
        if (shouldReconnect) {
          // If the server requires restart (e.g. 515), we reconnect immediately. Otherwise backoff slightly.
          const delay = statusCode === DisconnectReason.restartRequired ? 1000 : 5000;
          if (reconnectTimer) clearTimeout(reconnectTimer);
          reconnectTimer = setTimeout(() => {
            connectToWhatsApp(usePairingCode).catch(console.error);
          }, delay);
        } else if (isLoggedOut && !isIntentionallyDisconnected) {
          // Logged out by user device or forbidden, remove credentials cleanly
          console.log("[WhatsApp] Session logged out. Cleaning auth data to prevent reconnect loop.");
          try {
            await fs.rm(authDir, { recursive: true, force: true });
          } catch (e) {
            console.error("[WhatsApp] Failed to clean auth dir:", e);
          }
        }
      } else if (connection === "open") {
        console.log("[WhatsApp] Connection opened successfully and session saved!");
        connectionStatus = "connected";
        qrCodeDataUrl = null;
        pairingCodeData = null;
      }
    });

    newSock.ev.on("creds.update", async () => {
      await saveCreds();
    });

    newSock.ev.on("messages.upsert", async (m) => {
      if (m.type === "notify" || m.type === "append") {
        for (const msg of m.messages) {
          if (!msg.key.fromMe && msg.message) {
            const sender = msg.key.remoteJid;
            if (sender && !sender.includes("@g.us") && !sender.includes("status@broadcast")) { // Ignore groups & status
              const textMessage = msg.message.conversation || 
                                msg.message.extendedTextMessage?.text ||
                                msg.message.ephemeralMessage?.message?.extendedTextMessage?.text ||
                                msg.message.ephemeralMessage?.message?.conversation ||
                                msg.message.imageMessage?.caption ||
                                msg.message.videoMessage?.caption ||
                                msg.message.documentMessage?.caption ||
                                msg.message.templateButtonReplyMessage?.selectedId ||
                                msg.message.buttonsResponseMessage?.selectedButtonId ||
                                msg.message.listResponseMessage?.singleSelectReply?.selectedRowId;
              
              if (textMessage) {
                console.log(`[WhatsApp] Received message from ${sender}: "${textMessage}"`);
                await queueMessage(sender, textMessage, msg.pushName || "Customer");
              } else {
                // Check for voice note / audio message
                const audioMsg = msg.message.audioMessage ||
                  msg.message.ephemeralMessage?.message?.audioMessage ||
                  msg.message.viewOnceMessage?.message?.audioMessage ||
                  msg.message.viewOnceMessageV2?.message?.audioMessage;

                if (audioMsg) {
                  console.log(`[WhatsApp] Received voice message from ${sender} (Duration: ${audioMsg.seconds || "?"}s, PTT: ${audioMsg.ptt ? "Yes" : "No"}). Initiating Deepgram transcription...`);
                  try {
                    const audioBuffer = await downloadMediaMessage(
                      msg,
                      'buffer',
                      {},
                      {
                        logger: pino({ level: "silent" }) as any,
                        reuploadRequest: newSock.updateMediaMessage,
                      }
                    );

                    if (audioBuffer && audioBuffer.length > 0) {
                      const result = await transcribeAudio(audioBuffer as Buffer, {
                        customerJid: sender,
                        mimetype: audioMsg.mimetype || "audio/ogg; codecs=opus",
                      });

                      if (result.success && result.transcript) {
                        console.log(`[WhatsApp] Voice message transcribed via ${result.providerUsed}: "${result.transcript}"`);
                        await queueMessage(sender, result.transcript, msg.pushName || "Customer");
                      } else {
                        console.warn(`[WhatsApp] Voice message transcription failed: ${result.error}`);
                      }
                    }
                  } catch (err: any) {
                    console.error(`[WhatsApp] Error processing voice note from ${sender}:`, err);
                  }
                }
              }
            }
          }
        }
      }
    });
  } finally {
    isConnecting = false;
  }
}

export function getWhatsAppConnectionStatus(): "connecting" | "connected" | "disconnected" {
  return connectionStatus;
}

export function getWhatsAppSocket(): ReturnType<typeof makeWASocket> | null {
  return sock;
}

export interface WhatsAppGroupInfo {
  id: string;
  name: string;
  totalMembers: number;
  participants: Array<{ id: string; phoneNumber: string; admin?: string | null }>;
}

let cachedGroups: WhatsAppGroupInfo[] | null = null;
let lastGroupFetchTime = 0;
const GROUP_CACHE_TTL = 5 * 60 * 1000; // 5 minutes

export async function fetchAllGroups(): Promise<WhatsAppGroupInfo[] | null> {
  const cachePath = path.join(DATA_DIR, "groups_cache.json");

  // Use in-memory cache if valid
  if (cachedGroups && Date.now() - lastGroupFetchTime < GROUP_CACHE_TTL) {
    return cachedGroups;
  }

  if (!sock || connectionStatus !== "connected") {
    // If not connected, return cached groups from data/groups_cache.json if available
    try {
      const data = await fs.readFile(cachePath, "utf-8");
      return JSON.parse(data);
    } catch {
      return null; // Return null instead of [] to indicate failure to fetch
    }
  }

  try {
    const groupsObj = await sock.groupFetchAllParticipating();
    const result: WhatsAppGroupInfo[] = [];

    for (const [jid, meta] of Object.entries(groupsObj)) {
      const participants = (meta.participants || []).map((p: any) => {
        const rawId = p.id || "";
        const cleanNumber = rawId.split("@")[0].split(":")[0];
        return {
          id: rawId,
          phoneNumber: cleanNumber.startsWith("+") ? cleanNumber : `+${cleanNumber}`,
          admin: p.admin || null,
        };
      });

      result.push({
        id: jid,
        name: meta.subject || "Unnamed Group",
        totalMembers: participants.length || meta.size || 0,
        participants,
      });
    }

    // Update in-memory cache
    cachedGroups = result;
    lastGroupFetchTime = Date.now();

    // Cache groups for offline/setup accessibility
    try {
      await fs.writeFile(cachePath, JSON.stringify(result, null, 2));
    } catch (err) {
      console.warn("[WhatsApp] Failed to write groups cache:", err);
    }

    return result;
  } catch (error: any) {
    if (error?.message?.includes("Connection Closed")) {
      console.warn("[WhatsApp] Warning: Connection closed while fetching groups. Using cache.");
    } else {
      console.error("[WhatsApp] Error fetching participating groups:", error);
    }
    // Fallback to cache
    try {
      const data = await fs.readFile(cachePath, "utf-8");
      return JSON.parse(data);
    } catch {
      return null; // Return null to indicate complete failure
    }
  }
}

export async function sendCampaignMessage(jidOrPhone: string, text: string): Promise<{ success: boolean; error?: string }> {
  if (!sock || connectionStatus !== "connected") {
    return { success: false, error: "WhatsApp is not connected." };
  }

  try {
    let clean = jidOrPhone.trim();
    if (!clean.includes("@")) {
      clean = clean.replace(/[^0-9]/g, "");
      clean = `${clean}@s.whatsapp.net`;
    }
    
    await sock.sendMessage(clean, { text });
    return { success: true };
  } catch (error: any) {
    console.error(`[WhatsApp] Failed to send campaign message to ${jidOrPhone}:`, error);
    return {
      success: false,
      error: error?.message || error?.toString() || "Unknown WhatsApp transmission error",
    };
  }
}

export async function sendMessage(jid: string, text: string) {
  if (!sock) {
    console.warn("[WhatsApp] Cannot send message: WhatsApp socket is not connected.");
    return;
  }
  try {
    const formattedJid = jid.includes("@") ? jid : `${jid}@s.whatsapp.net`;
    console.log(`[WhatsApp] Sending reply to ${formattedJid}: "${text}"`);
    await sock.sendMessage(formattedJid, { text });
    console.log(`[WhatsApp] Message successfully sent to ${formattedJid}`);
  } catch (error) {
    console.error(`[WhatsApp] Error delivering message to ${jid}:`, error);
  }
}

export async function sendToolImage(jid: string, imagePath: string, caption?: string): Promise<boolean> {
  if (!sock) {
    console.warn("[WhatsApp] Cannot send image: WhatsApp socket is not connected.");
    return false;
  }
  try {
    const formattedJid = jid.includes("@") ? jid : `${jid}@s.whatsapp.net`;
    const fullPath = path.isAbsolute(imagePath) ? imagePath : path.join(ROOT_DIR, imagePath);
    
    // Verify file exists
    try {
      await fs.access(fullPath);
    } catch {
      console.warn(`[WhatsApp] Tool image file not found on disk at: ${fullPath}`);
      return false;
    }

    const imageBuffer = await fs.readFile(fullPath);
    console.log(`[WhatsApp] Sending tool image (${path.basename(fullPath)}) to ${formattedJid}`);
    
    await sock.sendMessage(formattedJid, {
      image: imageBuffer,
      caption: caption || undefined
    });
    
    console.log(`[WhatsApp] Tool image successfully sent to ${formattedJid}`);
    return true;
  } catch (error) {
    console.error(`[WhatsApp] Error sending tool image to ${jid}:`, error);
    return false;
  }
}

export function getSocket() {
  return sock;
}

export function getConnectionStatus() {
  return connectionStatus;
}

export function setupWhatsAppRoutes(app: Express) {
  app.get("/api/whatsapp/status", (req, res) => {
    res.json({
      status: connectionStatus,
      qr: qrCodeDataUrl,
      pairingCode: pairingCodeData
    });
  });

  app.post("/api/whatsapp/connect", async (req, res) => {
    if (connectionStatus === "disconnected") {
      await connectToWhatsApp(false);
    }
    res.json({ success: true, status: connectionStatus });
  });

  app.post("/api/whatsapp/pair", async (req, res) => {
    const { phoneNumber } = req.body;
    if (!phoneNumber) return res.status(400).json({ error: "Phone number required" });
    
    try {
      // Disconnect cleanly without triggering logout to avoid deleting auth folder concurrently
      if (sock && connectionStatus !== "disconnected") {
         isIntentionallyDisconnected = true;
         sock.ws.close();
         connectionStatus = "disconnected";
         await new Promise(resolve => setTimeout(resolve, 500)); // wait for socket to close
      }
      
      await connectToWhatsApp(true);
      
      const cleanNumber = phoneNumber.replace(/[^0-9]/g, '');
      
      // Wait a bit for socket to be ready
      await new Promise(resolve => setTimeout(resolve, 1500));
      
      if (!sock?.authState.creds.registered) {
        const code = await sock!.requestPairingCode(cleanNumber);
        pairingCodeData = code;
        res.json({ success: true, code });
      } else {
        res.status(400).json({ error: "Already registered/connected." });
      }
    } catch (error: any) {
      console.error(error);
      res.status(500).json({ error: error.message });
    }
  });

  app.post("/api/whatsapp/send", async (req, res) => {
    try {
      const { phoneNumber, message } = req.body;
      if (!phoneNumber || !message) {
        return res.status(400).json({ error: "Phone number and message are required." });
      }
      if (connectionStatus !== "connected" || !sock) {
        return res.status(400).json({ error: "WhatsApp is not connected." });
      }

      await sendMessage(phoneNumber, message);
      // Also update customer memory
      const { updateCustomerMemory } = await import("./memory.js");
      await updateCustomerMemory(phoneNumber, message, "agent");

      res.json({ success: true });
    } catch (err: any) {
      console.error("[WhatsApp] Failed to send manual message:", err);
      res.status(500).json({ error: err?.message || "Failed to send message" });
    }
  });

  app.post("/api/whatsapp/disconnect", async (req, res) => {
    if (sock) {
      isIntentionallyDisconnected = true;
      sock.logout().catch(() => sock?.ws?.close());
      connectionStatus = "disconnected";
      pairingCodeData = null;
      qrCodeDataUrl = null;
      // Explicit user disconnect deletes auth folder
      const authDir = getAuthDir();
      await fs.rm(authDir, { recursive: true, force: true }).catch(console.error);
    }
    res.json({ success: true });
  });
}

// Auto-start WhatsApp connection on server boot if persistent auth credentials exist
setTimeout(async () => {
  try {
    const authDir = await ensureAuthDir();
    const creds = path.join(authDir, "creds.json");
    await fs.access(creds);
    console.log("[WhatsApp] Existing session found in data/auth. Auto-reconnecting to WhatsApp...");
    await connectToWhatsApp(false);
  } catch {
    console.log("[WhatsApp] No existing credentials found in data/auth. Ready for QR or Pairing code.");
  }
}, 1200);

