import path from "path";

/**
 * Calculates absolute root directory of application in both CJS bundle (dist/server.cjs) and TS dev mode (server.ts).
 */
function getAppRootDir(): string {
  if (process.env.APP_ROOT) {
    return path.resolve(process.env.APP_ROOT);
  }
  if (typeof __dirname !== "undefined") {
    const isDistFolder = path.basename(__dirname) === "dist";
    return isDistFolder ? path.resolve(__dirname, "..") : path.resolve(__dirname);
  }
  return process.cwd();
}

export const ROOT_DIR = getAppRootDir();
export const DATA_DIR = path.join(ROOT_DIR, "data");
export const DIST_DIR = path.join(ROOT_DIR, "dist");
export const AUTH_DIR = path.join(DATA_DIR, "auth");
export const TOOL_IMAGES_DIR = path.join(DATA_DIR, "tool-images");

// Force working directory to ROOT_DIR on module load to guarantee process.cwd() stability under cPanel Passenger
try {
  if (process.cwd() !== ROOT_DIR) {
    process.chdir(ROOT_DIR);
    console.log(`[Paths] Working directory synchronized to app root: ${ROOT_DIR}`);
  }
} catch (err) {
  console.warn(`[Paths] Could not set working directory to ${ROOT_DIR}:`, err);
}
